def run(self, args):
    progress_listener = make_progress_listener(args.localFileName, args.noProgress)
    download_dest = DownloadDestLocalFile(args.localFileName)

    range_start, range_end = None, None
    if hasattr(args, 'range') and args.range:
        try:
            parts = args.range.split('_')
            if len(parts) == 2:
                range_start = int(parts[0]) if parts[0] else None
                range_end = int(parts[1]) if parts[1] else None
            elif len(parts) == 1 and parts[0]:
                range_start = int(parts[0])
        except ValueError:
            raise ValueError("Invalid range format. Use START_END where START and END are integers.")

    self.api.download_file_by_id(args.fileId, download_dest, progress_listener,
                               range_start, range_end)
    self.console_tool._print_download_info(download_dest)
    return 0

